import type { ReactNode, SVGProps } from 'react';

/**
 * All chrome icons share a 16px box and a 1.25px stroke, matching Paper's rail.
 *
 * Everything the set covers is coolicons, by Kryston Schwarze, kept on its
 * native 24px grid by `Svg24` below — the tool glyphs and every generic panel
 * control alike. What stays hand-drawn is only what no general-purpose set
 * carries: gap, padding, baseline, corner radius, blend and boolean modes,
 * auto-layout, and the other marks that mean something only inside a design
 * tool.
 * https://www.figma.com/community/file/1249481440217147943
 */
function Svg({ children, size = 16, ...rest }: SVGProps<SVGSVGElement> & { children: ReactNode; size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.25}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
    >
      {children}
    </svg>
  );
}

/**
 * The same box, drawn on coolicons' 24px grid.
 *
 * The tool glyphs come from coolicons (Kryston Schwarze), which is drawn at 24
 * with a 2px stroke. Rescaling the paths to 16 would round every coordinate
 * onto a coarser grid, so the viewBox travels with them instead and only the
 * weight is converted: 1.25 on a 16 grid is 1.875 on a 24 one.
 */
function Svg24({ children, size = 16, ...rest }: SVGProps<SVGSVGElement> & { children: ReactNode; size?: number }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.875}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...rest}
    >
      {children}
    </svg>
  );
}

/** a deliberately irregular dot field — noise, not a grid */
function scatter(): ReactNode {
  const points: [number, number, number][] = [
    [3.2, 3.6, 1.05], [7.4, 2.9, 0.75], [11.8, 4.2, 1.05], [5.1, 6.6, 0.75],
    [9.4, 7.2, 1.05], [2.9, 9.8, 0.9], [12.4, 9.1, 0.75], [6.6, 11.4, 1.05],
    [10.4, 12.2, 0.9],
  ];
  return points.map(([cx, cy, r], index) => (
    <circle key={index} cx={cx} cy={cy} r={r} fill="currentColor" strokeWidth={0} />
  ));
}

